gWF(){return"\u0416\u043e\u049b. \u0416\u0430\u043b\u043f\u044b \u0435\u043b\u0434\u0456 \u043c\u0435\u043a\u0435\u043d \u0448\u0435\u0433\u0456 60 \u043a\u043c/\u0441\u0430\u0493."},
